import {registerChecks,assert,waitFor} from './advanced-checks.js';

// Also callable on /components/account/* by the parent's authorized browser audit.
// Geometry checks run before interactions can dismiss or alter a specimen.
export function checkAccountSourceLayout(scope){
 const all=selector=>[...(scope.matches?.(selector)?[scope]:[]),...scope.querySelectorAll(selector)];
 const box=node=>node.getBoundingClientRect();
 for(const card of all('.ely-api-profile-card')){
  const avatar=card.querySelector('.ely-api-profile-avatar, :scope > img'),identity=card.querySelector('.ely-suite-profile-identity');
  assert(avatar&&identity,'Profile avatar and identity must be present');
  const a=box(avatar),i=box(identity),c=box(card);
  assert(i.left>=a.right+8 && Math.abs(i.top-a.top)<12,'Profile identity must sit beside its avatar');
  assert(i.width>=Math.min(180,c.width-96),'Profile identity collapsed into a narrow column');
  const name=identity.querySelector('strong');
  if(name?.textContent==='Ada Lovelace')assert(box(name).height<30,'Profile name must fit on one line');
 }
 for(const providers of all('.ely-suite-providers'))for(const button of providers.querySelectorAll('button')){
  assert(Math.abs(box(button).width-box(providers).width)<=2,'OAuth button must fill its provider column');
 }
 for(const form of all('.ely-api-invitations fieldset')){
  const button=form.querySelector('button[type=submit]'),field=form.querySelector('select');
  if(button&&field)assert(Math.abs(box(button).bottom-box(field).bottom)<=2,'Invite button must align with the input row');
 }
 for(const group of all('.component-examples')){
  const get=name=>group.querySelector(`:scope > [data-ely-component="account/${name}"]`);
  const team=get('TeamMemberTable'),invites=get('InvitationList');
  if(team&&invites){assert(box(invites).top>=box(team).bottom+20,'Invitations must sit below members without overlap');assert(Math.abs(box(invites).left-box(team).left)<2,'Invitations must align with members');}
  const workspace=get('WorkspaceSwitcher'),account=get('AccountSwitcher'),user=get('UserMenu');
  if(workspace&&account&&user){assert(box(account).top>=box(workspace).bottom+6 && Math.abs(box(account).left-box(workspace).left)<2,'Account must sit below workspace');assert(box(user).left>=box(workspace).right+20 && Math.abs(box(user).top-box(workspace).top)<2,'User menu must sit beside the workspace column');}
  const bills=get('BillingHistory'),prompt=get('UpgradePrompt'),wall=get('Paywall');
  if(bills&&prompt&&wall){
   assert(box(wall).top>=box(prompt).bottom+12,'Paywall must sit below upgrade prompt');
   assert(Math.abs(box(wall).left-box(prompt).left)<2,'Paywall must align with upgrade prompt');
   if(box(group).width>=740)assert(box(wall).left>=box(bills).right+20,'Paywall must occupy the right billing column');
  }
 }
}

// Geometry must be measured in the parent's browser, not inferred from CSS text.
export function checkFormsVisual7Layout(scope){
 const all=selector=>[...(scope.matches?.(selector)?[scope]:[]),...scope.querySelectorAll(selector)];
 for(const radio of all('.ely-api-radio-group input[type=radio]')){const b=radio.getBoundingClientRect();assert(b.width>=14&&b.width<=18&&b.height>=14&&b.height<=18,'Radio must remain a compact native control');const label=radio.closest('label');if(label.closest('.component-live'))assert(label.getBoundingClientRect().height<=26,'Source radio label must fit on one line');}
 for(const group of all('.ely-api-radio-group')){const labels=[...group.querySelectorAll('label')];if(labels.length>1&&!group.classList.contains('is-row'))assert(labels[1].getBoundingClientRect().top>=labels[0].getBoundingClientRect().bottom,'Plan radios must stack vertically');}
 for(const rating of all('.ely-api-rating')){const stars=[...rating.querySelectorAll('[data-ely-rate]')];assert(Math.abs(rating.getBoundingClientRect().width-(stars.length*22-2))<=3,'Rating must use compact stars');for(const star of stars)assert(getComputedStyle(star).backgroundColor==='rgba(0, 0, 0, 0)','Rating must not paint selected rectangles');}
 for(const knob of all('[data-ely-knob]')){const b=knob.getBoundingClientRect();assert(Math.abs(b.width-48)<=1&&Math.abs(b.height-48)<=1,'Knob must be 48px');assert(knob.closest('.ely-api-knob-specimen').querySelector('[data-ely-knob-caption]')||!scope.closest?.('.component-live'),'Knob story needs its caption');}
 for(const group of all('.component-examples:has([data-ely-component="forms/CheckboxCard"])')){const cards=[...group.querySelectorAll('.ely-api-choice-card')];if(cards.length===3&&group.getBoundingClientRect().width>=640){const [a,b,c]=cards.map(card=>card.getBoundingClientRect());assert(Math.abs(a.top-b.top)<2&&c.top>=a.bottom+12,'Personal/Team must precede backup');assert(Math.abs(c.width-640)<=2,'Backup must span the 640px specimen');}}
}
const need=(root,selector)=>{const node=root.querySelector(selector);assert(node,`Missing ${selector}`);return node;};
const input=(node,value)=>{node.value=value;node.dispatchEvent(new Event('input',{bubbles:true}));node.dispatchEvent(new Event('change',{bubbles:true}));};
const field=async({root})=>{const node=root.querySelector('input[type=radio]:not(:checked)')||need(root,'input:not([type=hidden]),textarea,select');assert(!node.disabled,'Caller field disabled unexpectedly');if(node.tagName==='SELECT'){node.selectedIndex=Math.min(1,node.options.length-1);node.dispatchEvent(new Event('change',{bubbles:true}));assert(node.selectedOptions.length===1,'Option selection failed');}else if(['checkbox','radio'].includes(node.type)){const before=node.checked;node.click();assert(node.checked!==before,'Choice state did not toggle');}else{const value={number:'4',range:'4',date:'2026-10-21',month:'2026-11',week:'2026-W43',time:'13:30','datetime-local':'2026-10-21T13:30',color:'#228855',email:'changed@example.test',url:'https://example.test/changed'}[node.type]||(root.dataset.elyComponent.endsWith('/JsonInput')?'{"caller":"changed"}':'Changed caller value');input(node,value);assert(node.value===value,'Caller value was not retained');assert(node.checkValidity(),'Valid caller value was rejected');}if(node.name){const form=document.createElement('form');form.append(node.cloneNode(true));assert(new FormData(form).has(node.name)===(['checkbox','radio'].includes(node.type)?node.checked:true),'Native submission differs from choice state');}};
const submit=async({root,actions})=>{const form=need(root,'form[data-ely-submit]');for(const node of form.querySelectorAll('input[required],textarea[required]'))if(!node.value)input(node,node.type==='email'?'caller@example.test':node.type==='password'?'Example-only-123':'Caller completed value');assert(form.checkValidity(),'Valid caller form rejected');form.requestSubmit();assert(actions.some(event=>event.formData instanceof FormData&&event.values.length),'Native form values missing from host action');};
const checks={};
