export function checkChoiceCardState(root){
 const cards=[...root.querySelectorAll('.ely-api-choice-card')];assert(cards.length===2,'Caller choice cards missing');
 const controls=cards.map(card=>need(card,'input'));
 if(controls[0].type==='radio'){
  assert(controls.every(control=>control.type==='radio'&&control.name===controls[0].name)&&controls[0].name,'Radio cards must share a nonempty submission name');
  const next=controls.find(control=>!control.disabled&&!control.checked);assert(next,'Caller radio cards need another enabled choice');
  next.click();assert(next.checked&&controls.filter(control=>control.checked).length===1,'Radio card selection must be exclusive');
  next.click();assert(next.checked&&controls.filter(control=>control.checked).length===1,'Clicking selected radio must retain its selection');
  const other=controls.find(control=>control!==next&&!control.disabled);assert(other,'Caller radio cards need two enabled choices');other.click();assert(other.checked&&!next.checked&&controls.filter(control=>control.checked).length===1,'Choosing another radio must clear the previous selection');
 }else{
  assert(controls.every(control=>control.type==='checkbox'),'Checkbox cards must use checkboxes');
  const before=controls[0].checked,neighbor=controls[1].checked;controls[0].click();assert(controls[0].checked!==before,'Caller checkbox card did not toggle');assert(controls[1].checked===neighbor,'Checkbox card changed an independent choice');
 }
}
